import sys; sys.path.insert(0, str(WORK))
from cvlib import *
R = np.load(WORK/'base_reads.npz'); y=R['y']; res=np.load(WORK/'reserved.npy')
keep = np.setdiff1d(np.arange(768), res)
M = lambda L: R[f'mean_hidden_L{L}'][:,keep]
Y=np.eye(8)[y]
rng=np.random.RandomState(0)
def nys_cv(X, gamma, lams, ncent=768, seeds=(0,1), mode='rbf', lin=False):
    out={l:[] for l in lams}
    for s in seeds:
        f=folds(y,5,s); S={l:np.zeros((len(y),8)) for l in lams}
        for i in range(5):
            tr=np.where(f!=i)[0]; te=np.where(f==i)[0]
            mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6
            Z=(X-mu)/sd; d=Z.shape[1]
            Z=Z/np.linalg.norm(Z,axis=1,keepdims=True)  # unit-normalize (mimic LN)
            cidx=[]
            for c in range(8):
                ic=tr[y[tr]==c]; cidx+=list(rng.choice(ic, min(ncent//8,len(ic)), replace=False))
            C=Z[cidx]
            F=np.exp(gamma*(Z@C.T-1))
            if lin: F=np.concatenate([F, Z],1)
            Ftr=F[tr]; fm=Ftr.mean(0); Ftr=Ftr-fm; Fte=F[te]-fm
            G=Ftr.T@Ftr; B=Ftr.T@(Y[tr]-Y[tr].mean(0))
            for l in lams:
                S[l][te]=Fte@np.linalg.solve(G+l*np.eye(G.shape[0]),B)
        for l in lams: out[l].append((S[l].argmax(1)==y).mean())
    return {l:round(float(np.mean(v)),4) for l,v in out.items()}
